<script setup lang="ts">
import type { components } from '~/api/schema'; import { unwrap, versionHeaders } from '~/api/client'; import { displayError } from '~/utils/errors';
type Legal = components['schemas']['LegalEntity']; type Store = components['schemas']['Store'];
definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const portal = usePortal();
const step = ref(1); const entity = ref<Legal>(); const store = ref<Store>(); const documents = ref<components['schemas']['Document'][]>([]); const pending = ref(false); const message = ref('');
const legal = reactive({ kind: 'INDIVIDUAL' as 'INDIVIDUAL'|'COMPANY', legal_name: '', tax_identifier: '' });
const shop = reactive({ name: '', slug: '', contact_phone: '' });
const origin = reactive({ contact_name: '', phone: '', street: '', postal_code: '', area_id: '', latitude: undefined as number|undefined, longitude: undefined as number|undefined });
const bank = reactive({ bank_code: '', account_name: '', account_number: '' });
onMounted(async () => { try { await portal.loadStores(); if (portal.activeStore.value) { store.value = portal.activeStore.value; step.value = 4; } } catch { /* form remains usable */ } });
async function createEntity() { pending.value=true; message.value=''; try { entity.value=unwrap(await api.POST('/vendor/legal-entities',{params:{header:{'Idempotency-Key':crypto.randomUUID()}},body:{kind:legal.kind,legal_name:legal.legal_name,tax_identifier:legal.tax_identifier||undefined}})); step.value=2; } catch(cause){message.value=displayError(cause).message;} finally{pending.value=false;} }
async function createStore() { if(!entity.value)return; pending.value=true; message.value=''; try { store.value=unwrap(await api.POST('/vendor/stores',{params:{header:{'Idempotency-Key':crypto.randomUUID()}},body:{...shop,legal_entity_id:entity.value.id}})); await portal.loadStores(); portal.selectStore(store.value.id); step.value=3; } catch(cause){message.value=displayError(cause).message;} finally{pending.value=false;} }
async function saveOrigin() { if(!store.value)return; pending.value=true; message.value=''; try { unwrap(await api.PUT('/vendor/stores/{storeId}/origin',{params:{path:{storeId:store.value.id},header:{'Idempotency-Key':crypto.randomUUID()}},body:{contact_name:origin.contact_name,phone:origin.phone,street:origin.street,postal_code:origin.postal_code,area_id:origin.area_id||undefined,latitude:origin.latitude,longitude:origin.longitude}})); step.value=4; } catch(cause){message.value=displayError(cause).message;} finally{pending.value=false;} }
async function saveBank() { if(!store.value)return; pending.value=true; message.value=''; try { unwrap(await api.POST('/vendor/stores/{storeId}/bank-accounts',{params:{path:{storeId:store.value.id},header:{'Idempotency-Key':crypto.randomUUID()}},body:{...bank}})); step.value=5; } catch(cause){message.value=displayError(cause).message;} finally{pending.value=false;} }
async function submitStore() { if(!store.value)return; pending.value=true; message.value=''; try { store.value=unwrap(await api.POST('/vendor/stores/{storeId}/submit',{params:{path:{storeId:store.value.id},header:{...versionHeaders(store.value.row_version),'Idempotency-Key':crypto.randomUUID()}}})); await portal.loadStores(); message.value='Toko diajukan untuk peninjauan.'; step.value=6; } catch(cause){message.value=displayError(cause).message;} finally{pending.value=false;} }
useSeoMeta({title:'Onboarding vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Vendor</p><h1>Onboarding entitas dan toko</h1></div><span class="badge">Langkah {{ step }} dari 6</span></div><ol class="wizard-steps"><li v-for="n in 6" :key="n" :class="{active:n<=step}">{{ ['Identitas','Dokumen','Toko','Asal & rekening','Ringkasan','Selesai'][n-1] }}</li></ol><p v-if="message" class="surface" role="status">{{ message }}</p><form v-if="step===1" class="surface address-form" @submit.prevent="createEntity"><h2 class="form-span">Identitas legal</h2><label class="form-field">Jenis<select v-model="legal.kind"><option value="INDIVIDUAL">Individu</option><option value="COMPANY">Perusahaan</option></select></label><label class="form-field">Nama legal<input v-model.trim="legal.legal_name" required maxlength="200"></label><label class="form-field">NIK/NPWP<input v-model.trim="legal.tax_identifier" inputmode="numeric" pattern="[0-9. -]{15,24}"></label><button :disabled="pending">Simpan dan lanjut</button></form><section v-else-if="step===2" class="surface"><h2>Dokumen legal</h2><DocumentUploader v-if="entity" :legal-entity-id="entity.id" @uploaded="documents.push($event)"/><p>{{ documents.length }} dokumen diunggah.</p><button type="button" @click="step=3">Lanjut ke toko</button></section><form v-else-if="step===3 && !store" class="surface address-form" @submit.prevent="createStore"><h2 class="form-span">Profil toko</h2><label class="form-field">Nama toko<input v-model.trim="shop.name" required maxlength="200"></label><label class="form-field">Slug<input v-model.trim="shop.slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*"></label><label class="form-field">Telepon kontak<input v-model.trim="shop.contact_phone" required maxlength="32"></label><button :disabled="pending">Buat toko</button></form><section v-else-if="step===3 && store" class="surface"><h2>Toko {{ store.name }} sudah dibuat</h2><button @click="step=4">Lanjut</button></section><div v-else-if="step===4" class="onboarding-columns"><form class="surface address-form" @submit.prevent="saveOrigin"><h2 class="form-span">Alamat asal</h2><label class="form-field">Kontak<input v-model.trim="origin.contact_name" required></label><label class="form-field">Telepon<input v-model.trim="origin.phone" required></label><label class="form-field form-span">Alamat<textarea v-model.trim="origin.street" required/></label><label class="form-field">Kode pos<input v-model.trim="origin.postal_code" required pattern="[0-9]{5}"></label><label class="form-field">Area ID<input v-model.trim="origin.area_id" placeholder="Atau isi koordinat"></label><label class="form-field">Latitude<input v-model.number="origin.latitude" type="number" step="any"></label><label class="form-field">Longitude<input v-model.number="origin.longitude" type="number" step="any"></label><button :disabled="pending">Simpan asal</button></form><form class="surface address-form" @submit.prevent="saveBank"><h2 class="form-span">Rekening pencairan</h2><label class="form-field">Kode bank<input v-model.trim="bank.bank_code" required maxlength="30"></label><label class="form-field">Nama rekening<input v-model.trim="bank.account_name" required maxlength="200"></label><label class="form-field">Nomor rekening<input v-model.trim="bank.account_number" required maxlength="50"></label><button :disabled="pending || !store">Simpan rekening</button></form></div><section v-else-if="step===5" class="surface"><h2>Ringkasan pengajuan</h2><p><strong>{{ store?.name }}</strong> · {{ store?.status }}</p><p>Pastikan alamat asal memiliki Area ID atau koordinat dan dokumen legal sudah benar.</p><button :disabled="pending" @click="submitStore">Ajukan peninjauan</button></section><section v-else class="surface"><h2>Pengajuan diterima</h2><p>Status toko akan berubah setelah tim operasional memeriksa entitas, dokumen, rekening, dan asal pengiriman.</p><NuxtLink class="button" to="/vendor">Ke dashboard</NuxtLink></section></main></template>
